$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; elif test -f README.json; then cat README.json >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh api 'repos/BestNameYet/Terminals/contents/.devcontainer/devcontainer.json?ref=main' --jq .content | base64 --decode >/tmp/terminals-devcontainer-verified.json
node <<'NODE'
const fs=require('fs'), assert=require('assert');
const config=JSON.parse(fs.readFileSync('/tmp/terminals-devcontainer-verified.json','utf8'));
const expected="nohup bash -lc 'PORT=3000 npx @modelcontextprotocol/server-everything streamableHttp' > /tmp/mcp-everything.log 2>&1 < /dev/null &";
assert.strictEqual(config.postStartCommand,expected);
assert.deepStrictEqual(config.forwardPorts,[3000]);
assert.strictEqual(config.postCreateCommand,'npm install -g @modelcontextprotocol/server-everything');
require('child_process').execFileSync('bash',['-n','-c',config.postStartCommand]);
console.log('REMOTE_MAIN_CONFIGURATION_VERIFIED',true);
console.log('POST_START_COMMAND',config.postStartCommand);
console.log('FORWARDED_PORT',config.forwardPorts[0]);
console.log('VALID_BASH',true);
console.log('RUNTIME_SERVER_STARTED_BY_THIS_CHECK',false);
NODE
gh api repos/BestNameYet/Terminals/commits/main --jq .sha
